import React, { useEffect, useState } from "react";
import api from "../api";
import CreateUserForm from "./CreateUserForm";
import CreateTicketForm from "./CreateTicketForm";
import io from "socket.io-client";

interface User {
  _id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: "Admin" | "Agent" | "User";
  departments: string[];
  createdAt: string;
}

interface TicketUserRef {
  _id: string;
  firstName: string;
  lastName: string;
}

interface Ticket {
  _id: string;
  title: string;
  status: string;
  priority: string;
  category: string;
  description?: string;
  createdBy?: TicketUserRef;
  assignee?: TicketUserRef | null;
  createdAt: string;
  comments?: {
    _id: string;
    body: string;
    createdAt: string;
    author?: { email?: string };
  }[];
}

interface Props {
  name: string;
}

const DEPARTMENT_OPTIONS = ["Technical", "Billing", "General"];
const STATUS_OPTIONS = ["Open", "In Progress", "Closed"];
const PRIORITY_OPTIONS = ["Low", "Medium", "High"];
const CATEGORY_OPTIONS = ["Technical", "Billing", "General"];

const AdminDashboard: React.FC<Props> = ({ name }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [loadingTickets, setLoadingTickets] = useState(true);

  const [showCreateUser, setShowCreateUser] = useState(false);
  const [showCreateTicket, setShowCreateTicket] = useState(false);

  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [userEdits, setUserEdits] = useState<Partial<User>>({});

  const [editingTicketId, setEditingTicketId] = useState<string | null>(null);
  const [ticketEdits, setTicketEdits] = useState<
    Partial<Ticket> & { assigneeId?: string | null }
  >({});

  const [selectedTicket, setSelectedTicket] = useState<Ticket | null>(null);
  const [showTicketModal, setShowTicketModal] = useState(false);
  const [newComment, setNewComment] = useState("");

  const [socket, setSocket] = useState<any>(null);

  // =======================
  // FETCHING
  // =======================

  const fetchUsers = async () => {
    try {
      const res = await api.get<User[]>("/users");
      setUsers(res.data);
    } catch {
      //
    } finally {
      setLoadingUsers(false);
    }
  };

  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setTickets(res.data);
    } finally {
      setLoadingTickets(false);
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchTickets();
  }, []);

  // =======================
  // SOCKET SETUP
  // =======================

  useEffect(() => {
    const s = io("http://localhost:5050", { withCredentials: true } as any);
    setSocket(s);
    return () => s.disconnect();
  }, []);

  useEffect(() => {
    if (!socket) return;

    socket.on("ticketCreated", fetchTickets);

    socket.on("ticketUpdated", (updated: Ticket) => {
      setTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );

      setSelectedTicket((prev) =>
        prev && prev._id === updated._id ? updated : prev
      );
    });

    socket.on("ticketDeleted", (ticketId: string) => {
      setTickets((prev) => prev.filter((t) => t._id !== ticketId));

      if (selectedTicket?._id === ticketId) {
        setSelectedTicket(null);
        setShowTicketModal(false);
      }
    });

    return () => {
      socket.off("ticketCreated");
      socket.off("ticketUpdated");
      socket.off("ticketDeleted");
    };
  }, [socket, selectedTicket]);

  // =======================
  // HELPERS
  // =======================

  const agents = users.filter((u) => u.role === "Agent");
  const adminCount = users.filter((u) => u.role === "Admin").length;
  const isLastAdmin = (u: User) => u.role === "Admin" && adminCount === 1;

  // =======================
  // USER ACTIONS
  // =======================

  const startEditUser = (u: User) => {
    setEditingUserId(u._id);
    setUserEdits({ ...u });
  };

  const saveUser = async () => {
    if (!editingUserId) return;

    const payload = {
      firstName: userEdits.firstName,
      lastName: userEdits.lastName,
      email: userEdits.email,
      role: userEdits.role,
      departments:
        userEdits.role === "Agent" ? userEdits.departments || [] : [],
    };

    const res = await api.patch<User>(`/users/${editingUserId}`, payload);
    setUsers((prev) =>
      prev.map((u) => (u._id === res.data._id ? res.data : u))
    );

    setEditingUserId(null);
    setUserEdits({});
  };

  const deleteUser = async (u: User) => {
    if (isLastAdmin(u)) return;
    await api.delete(`/users/${u._id}`);
    setUsers((prev) => prev.filter((x) => x._id !== u._id));
  };

  // =======================
  // TICKET ACTIONS
  // =======================

  const openTicket = async (t: Ticket) => {
    const res = await api.get<Ticket>(`/tickets/${t._id}`);
    setSelectedTicket(res.data);
    setNewComment("");
    setShowTicketModal(true);
  };

  const saveTicket = async () => {
    if (!editingTicketId) return;

    const payload = {
      title: ticketEdits.title,
      status: ticketEdits.status,
      priority: ticketEdits.priority,
      category: ticketEdits.category,
      assignee: ticketEdits.assigneeId || null,
    };

    const res = await api.patch<Ticket>(`/tickets/${editingTicketId}`, payload);

    setTickets((prev) =>
      prev.map((t) => (t._id === res.data._id ? res.data : t))
    );

    setEditingTicketId(null);
    setTicketEdits({});
  };

  const addComment = async () => {
    if (!selectedTicket || !newComment.trim()) return;

    const res = await api.post<Ticket>(
      `/tickets/${selectedTicket._id}/comments`,
      {
        body: newComment,
      }
    );

    setSelectedTicket(res.data);
    setNewComment("");
  };

  // =======================
  // RENDER
  // =======================

  return (
    <div>
      <h2>Welcome, Admin {name}</h2>

      {/* USERS */}
      <h3>User Management</h3>
      <button onClick={() => setShowCreateUser(true)}>Create User</button>

      {showCreateUser && (
        <CreateUserForm
          onClose={() => setShowCreateUser(false)}
          onCreated={fetchUsers}
        />
      )}

      {loadingUsers ? (
        <p>Loading users...</p>
      ) : (
        <table border={1}>
          <tbody>
            {users.map((u) => (
              <tr key={u._id}>
                <td>{u.firstName}</td>
                <td>{u.lastName}</td>
                <td>{u.email}</td>
                <td>{u.role}</td>
                <td>
                  <button onClick={() => startEditUser(u)}>Edit</button>
                  <button
                    onClick={() => deleteUser(u)}
                    disabled={isLastAdmin(u)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* TICKETS */}
      <h3>Tickets</h3>
      <button onClick={() => setShowCreateTicket(true)}>Create Ticket</button>

      {showCreateTicket && (
        <CreateTicketForm
          users={users}
          onClose={() => setShowCreateTicket(false)}
          onCreated={fetchTickets}
        />
      )}

      {loadingTickets ? (
        <p>Loading tickets...</p>
      ) : (
        <table border={1}>
          <tbody>
            {tickets.map((t) => (
              <tr key={t._id}>
                <td>{t.title}</td>
                <td>{t.status}</td>
                <td>{t.priority}</td>
                <td>
                  <button onClick={() => openTicket(t)}>Open</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* MODAL */}
      {showTicketModal && selectedTicket && (
        <div className="modal">
          <h3>{selectedTicket.title}</h3>

          <p>{selectedTicket.description}</p>

          <h4>Comments</h4>
          {selectedTicket.comments?.map((c) => (
            <p key={c._id}>
              <strong>{c.author?.email}:</strong> {c.body}
            </p>
          ))}

          <textarea
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
          />

          <button onClick={addComment}>Add Comment</button>
          <button
            onClick={() => {
              setSelectedTicket(null);
              setShowTicketModal(false);
            }}
          >
            Close
          </button>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
